import type { KnowledgeBaseArticle } from '../types';

export type KnowledgeSection = 'standards' | 'workflows' | 'templates';

export const KNOWLEDGE_SECTION_LABELS: Record<KnowledgeSection, string> = {
  standards: 'Quy chuẩn',
  workflows: 'Quy trình',
  templates: 'Biểu mẫu',
};

const KNOWLEDGE_SECTION_MARKER = 'knowledge-section';
const KNOWLEDGE_SUMMARY_MARKER = 'knowledge-summary';

export const stripKnowledgeMeta = (content = '') =>
  content.replace(/^<!--\s*knowledge-section:\s*(standards|workflows|templates)\s*-->\s*/i, '').replace(/^<!--\s*knowledge-summary:[\s\S]*?-->\s*/i, '');

export const withKnowledgeSection = (section: KnowledgeSection, content = '', summary = '') => {
  const cleanContent = stripKnowledgeMeta(content);
  const summaryBlock = summary.trim() ? `<!-- ${KNOWLEDGE_SUMMARY_MARKER}:\n${summary.trim()}\n-->\n` : '';
  return `<!-- ${KNOWLEDGE_SECTION_MARKER}: ${section} -->\n${summaryBlock}${cleanContent}`;
};

export const getKnowledgeSection = (
  article: Pick<KnowledgeBaseArticle, 'content' | 'title' | 'category'>
): KnowledgeSection => {
  const marker = article.content.match(/<!--\s*knowledge-section:\s*(standards|workflows|templates)\s*-->/i);
  if (marker?.[1]) return marker[1].toLowerCase() as KnowledgeSection;
  const text = `${article.title} ${article.category}`.toLowerCase();
  if (text.includes('biểu mẫu') || text.includes('bàn giao') || text.includes('tăng ca')) return 'templates';
  if (text.includes('quy trình') || text.includes('mô tả công việc')) return 'workflows';
  return 'standards';
};

const getKnowledgeSummary = (content = '') => {
  const marker = content.match(/<!--\s*knowledge-summary:\s*([\s\S]*?)\s*-->/i);
  if (marker?.[1]?.trim()) return marker[1].trim();
  return 'Tài liệu này chưa có phần tóm tắt nội dung. Vui lòng đọc bản xem trước hoặc cập nhật lại tóm tắt cho tài liệu.';
};

export const getKnowledgeSummaryBullets = (content = '') => {
  const summary = getKnowledgeSummary(content);
  if (!summary.trim()) return [];

  const explicitBullets = summary
    .split(/\n+/)
    .map(line => line.replace(/^[-*•]\s*/, '').trim())
    .filter(Boolean);

  if (explicitBullets.length > 1) return explicitBullets;

  const sentenceBullets = summary
    .split(/(?<=[.!?。])\s+|(?<=\.)\s+|(?<=\?)\s+|(?<=!)\s+/)
    .map(line => line.trim())
    .filter(Boolean);

  return sentenceBullets.length > 1 ? sentenceBullets : explicitBullets;
};

export const getKnowledgeSummaryMarkdown = (content = '') =>
  getKnowledgeSummaryBullets(content)
    .map(item => `- ${item}`)
    .join('\n');

