const article = (
  section: KnowledgeSection,
  id: string,
  category: KnowledgeBaseArticle['category'],
  title: string,
  sourceFileName: string,
  summary: string,
  body: string
): KnowledgeBaseArticle => ({
  id, category, title,
  content: withKnowledgeSection(section, body, KNOWLEDGE_SUMMARY_OVERRIDES[id] || summary),
  updatedAt: now, sourceFileName,
  sourcePreviewUrl: `/knowledge-previews/${id}.pdf`,
  sourcePageImages: KNOWLEDGE_PAGE_IMAGE_COUNTS[id]
    ? Array.from(
        { length: KNOWLEDGE_PAGE_IMAGE_COUNTS[id] },
        (_, index) => `/knowledge-page-images/${id}/page-${index + 1}.png?v=3`
      )
    : undefined,
  sourceFileType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
});

